import numpy as np


class LogicNeuron:
    """A neuron that implements logical operations using continuous relaxation."""

    def __init__(self, n_inputs, logic_type='and'):
        self.logic_type = logic_type
        if logic_type == 'and':
            self.weights = np.ones(n_inputs) * 10.0
        elif logic_type == 'or':
            self.weights = np.ones(n_inputs) * 10.0
        else:
            self.weights = np.random.randn(n_inputs)
        self.bias = -np.sum(self.weights) / 2

    def _sigmoid(self, x):
        """Numerically stable sigmoid."""
        return np.where(x >= 0,
                       1 / (1 + np.exp(-x)),
                       np.exp(x) / (1 + np.exp(x)))

    def forward(self, x):
        """Compute logical operation output (continuous relaxation)."""
        z = np.dot(self.weights, x) + self.bias

        if self.logic_type == 'and':
            return self._sigmoid(z)
        elif self.logic_type == 'or':
            return self._sigmoid(z)
        elif self.logic_type == 'not':
            return self._sigmoid(-x[0])
        return self._sigmoid(z)


class LogicLayer:
    """A layer of logic neurons implementing a logical formula."""

    def __init__(self, n_inputs, n_neurons, logic_types=None):
        self.neurons = []
        if logic_types is None:
            logic_types = ['and'] * n_neurons

        for i in range(n_neurons):
            neuron = LogicNeuron(n_inputs, logic_types[i])
            self.neurons.append(neuron)

    def forward(self, x):
        """Forward pass through all logic neurons."""
        outputs = []
        for neuron in self.neurons:
            outputs.append(neuron.forward(x))
        return np.array(outputs)


def logic_to_network(x1, x2, formula='x1 AND x2'):
    """Build a logic neural network for a given formula."""
    x = np.array([x1, x2])

    if 'AND' in formula:
        neuron = LogicNeuron(2, 'and')
    elif 'OR' in formula:
        neuron = LogicNeuron(2, 'or')
    else:
        neuron = LogicNeuron(2, 'and')

    return neuron.forward(x)


if __name__ == "__main__":
    np.random.seed(42)

    and_neuron = LogicNeuron(2, 'and')
    print("AND gate:")
    for x1 in [0, 0, 1, 1]:
        for x2 in [0, 1, 0, 1]:
            out = logic_to_network(x1, x2, 'x1 AND x2')
            print(f"  ({x1}, {x2}) -> {out:.4f}")

    or_neuron = LogicNeuron(2, 'or')
    print("\nOR gate:")
    for x1 in [0, 0, 1, 1]:
        for x2 in [0, 1, 0, 1]:
            x = np.array([x1, x2])
            out = or_neuron.forward(x)
            print(f"  ({x1}, {x2}) -> {out:.4f}")
